mapper.insert:
/* 지출 등록 */
INSERT INTO EXPND
     ( PET_SN
     , MBR_SN
     , RECPT_SN
     , EXPND_CLSF_CD
     , EXPND_INPT_MTH_CD
     , EXPND_AMT
     , EXPND_PLCUS_NM
     , DTL_MTTR
     , EXPND_YMD
     , IDMPT_DMND_ID
     , DEL_YN
     , REG_DT
     , MDFCN_DT
     )
VALUES
     ( #{petSn}
     , #{mbrSn}
     , #{recptSn}
     , #{expndClsfCd}
     , #{expndInptMthCd}
     , #{expndAmt}
     , #{expndPlcusNm}
     , #{dtlMttr}
     , #{expndYmd}
     , #{idmptDmndId}
     , 'N'
     , NOW()
     , NOW()
     )

mapper.select:
/* 멱등 요청 ID 로 내 지출 조회 */ SELECT FROM EXPND E LEFT JOIN PET P ON P.PET_SN = E.PET_SN AND P.DEL_YN = 'N' WHERE E.MBR_SN = #{mbrSn} AND E.DEL_YN = 'N' AND E.IDMPT_DMND_ID IN
#{idmptDmndId}
ORDER BY E.EXPND_SN

/* 같은 날짜·카테고리·금액·반려동물의 내 지출 조회(공용은 공용끼리, 사용처·내용 제외) */
SELECT 
  FROM EXPND E
  LEFT JOIN PET P
    ON P.PET_SN = E.PET_SN
   AND P.DEL_YN = 'N'
 WHERE E.MBR_SN = #{mbrSn}
   AND E.DEL_YN = 'N'
   AND E.EXPND_YMD = #{expndYmd}
   AND E.EXPND_CLSF_CD = #{expndClsfCd}
   AND

        (E.PET_SN <=> #{line.petSn} AND E.EXPND_AMT = #{line.expndAmt})

 ORDER BY E.EXPND_SN

/* 기간 내 지출 합계 */
SELECT COALESCE(SUM(EXPND_AMT), 0)
  FROM EXPND
 WHERE MBR_SN = #{mbrSn}
   AND DEL_YN = 'N'
   AND EXPND_YMD BETWEEN #{startYmd} AND #{endYmd}

/* 알림 받을 월 지출 한도 조회(한도 없음·알림 끔이면 NULL) */
SELECT CASE WHEN EXPND_LIM_NOTI_RCPTN_YN = 'Y' THEN MM_EXPND_LIM_AMT END
  FROM MBR
 WHERE MBR_SN = #{mbrSn}
